/*
 * vphone-linux: bare-metal AArch64 FP / Neon differential test.
 *
 * Runs every instruction form in tests.inc (generated by tests.py) over
 * random and edge-case operands (NaNs with payloads, infinities, denormals,
 * +-0, values that round to the minimum normal, integer limits, ties) under
 * a set of FPCR settings (all rounding modes, FZ, DN, AH, FIZ, NEP, FZ16,
 * AHP), and prints a hash per instruction form of every result register
 * (all 128 bits) and of FPSR after each instruction, and of FPSR accumulated
 * over a batch of instructions with an exception taken in the middle.
 *
 * Run it on the same QEMU with VPHONE_NATIVE_FP=1 and =0 (see run.sh): the
 * native TCG FP path and the softfloat helpers must agree on every line.
 *
 * SPDX-License-Identifier: GPL-2.0-or-later
 */
typedef unsigned long u64;
typedef unsigned int u32;
typedef unsigned short u16;
typedef struct { u64 lo, hi; } __attribute__((aligned(16))) v128;

#ifndef ITERS
#define ITERS 1000
#endif
#define BATCH 48
#ifndef SEED
#define SEED 0x2545f4914f6cdd1dull
#endif

static v128 N, M, A, D;

struct test {
    const char *name;
    void (*fn)(void);
    int esz;        /* lane size: 1 h, 2 s, 3 d */
    int intin;      /* inputs are integers */
};
#include "tests.inc"

#define UART0 0x09000000UL
static void putc_(char c)
{
    volatile u32 *uart = (volatile u32 *)UART0;
    while (uart[0x18 / 4] & (1 << 5)) {
    }
    uart[0] = (u32)c;
}
static void puts_(const char *s)
{
    while (*s) {
        if (*s == '\n') {
            putc_('\r');
        }
        putc_(*s++);
    }
}
static void putx(u64 v)
{
    for (int i = 60; i >= 0; i -= 4) {
        putc_("0123456789abcdef"[(v >> i) & 15]);
    }
}
void fatal_exception(u64 vec, u64 esr, u64 elr, u64 far)
{
    puts_("\nFATAL exception esr=");
    putx(esr);
    puts_(" elr=");
    putx(elr);
    puts_("\n");
}

/* ---- random operands ---- */
static u64 rng = 0x2545f4914f6cdd1dull;
static u64 rnd(void)
{
    rng ^= rng >> 12;
    rng ^= rng << 25;
    rng ^= rng >> 27;
    return rng * 0x2545f4914f6cdd1dull;
}

static const u16 edge16[] = {
    0x0000, 0x8000, 0x0001, 0x03ff, 0x0400, 0x0401, 0x7bff, 0x7c00, 0xfc00,
    0x7e00, 0xfe01, 0x7c01, 0x7d23, 0x3c00, 0xbc00, 0x3800, 0x3e00, 0x4100,
    0x3bff, 0x3c01, 0x2000, 0x1c00, 0x0200, 0x7800, 0xf800, 0x5bff, 0x57ff,
};
static const u32 edge32[] = {
    0x00000000, 0x80000000, 0x00000001, 0x007fffff, 0x00800000, 0x00800001,
    0x7f7fffff, 0xff7fffff, 0x7f800000, 0xff800000, 0x7fc00000, 0xffc00001,
    0x7f800001, 0xffa00005, 0x7fe12345, 0x3f800000, 0xbf800000, 0x3f000000,
    0x3fc00000, 0x40200000, 0xbf000000, 0xc0200000, 0x4f000000, 0x4effffff,
    0xcf000000, 0xcf000001, 0x5f000000, 0x5effffff, 0xdf000000, 0xdf000001,
    0x4b800000, 0x4b000001, 0x20000000, 0x1fffffff, 0x20000001, 0x3f7fffff,
    0x3f800001, 0x00400000, 0x80800000, 0x807fffff, 0x7f000000, 0x4f800000,
    0x477fe000, 0x38800000, 0x33800000, 0x387fc000, 0x00ffffff, 0x3effffff,
};
static const u64 edge64[] = {
    0, 0x8000000000000000ull, 1, 0x000fffffffffffffull, 0x0010000000000000ull,
    0x0010000000000001ull, 0x7fefffffffffffffull, 0xffefffffffffffffull,
    0x7ff0000000000000ull, 0xfff0000000000000ull, 0x7ff8000000000000ull,
    0xfff8000000000001ull, 0x7ff0000000000001ull, 0xfff4000000000005ull,
    0x7ffc123456789abcull, 0x3ff0000000000000ull, 0xbff0000000000000ull,
    0x3fe0000000000000ull, 0x3ff8000000000000ull, 0x4004000000000000ull,
    0xbfe0000000000000ull, 0x41e0000000000000ull, 0x41dfffffffc00000ull,
    0x41dfffffffe00000ull, 0x41dfffffffffffffull, 0xc1e0000000000000ull,
    0xc1e0000000200000ull, 0x43e0000000000000ull, 0x43dfffffffffffffull,
    0xc3e0000000000000ull, 0xc3e0000000000001ull, 0x4340000000000000ull,
    0x4330000000000001ull, 0x2000000000000000ull, 0x1fffffffffffffffull,
    0x2000000000000001ull, 0x3fefffffffffffffull, 0x3ff0000000000001ull,
    0x36a0000000000000ull, 0x3810000000000000ull, 0x380fffffe0000000ull,
    0x47efffffe0000000ull, 0x47f0000000000000ull, 0x3690000000000000ull,
    0x001fffffffffffffull, 0x3fdfffffffffffffull, 0x7fe0000000000000ull,
};

#define ELEMS(a) (sizeof(a) / sizeof((a)[0]))

/* One FP lane of 2 << esz bytes. */
static u64 fp_lane(int esz)
{
    int ebits = esz == 1 ? 5 : esz == 2 ? 8 : 11;
    int mbits = esz == 1 ? 10 : esz == 2 ? 23 : 52;
    int bias = (1 << (ebits - 1)) - 1;
    u64 sign = (rnd() & 1) << (ebits + mbits);
    u64 man = rnd() & ((1ull << mbits) - 1);
    u64 r = rnd();
    long e;

    switch (r % 12) {
    case 0: case 1: case 2:
        if (esz == 1) {
            return edge16[(r >> 8) % ELEMS(edge16)];
        } else if (esz == 2) {
            return edge32[(r >> 8) % ELEMS(edge32)];
        }
        return edge64[(r >> 8) % ELEMS(edge64)];
    case 3:                                 /* any bits */
        return rnd() & (esz == 3 ? ~0ull : (1ull << (16 << (esz - 1))) - 1);
    case 4:                                 /* tiny: denormal, about the min normal */
        e = (r >> 8) % 3;
        if ((r >> 12) & 1) {
            man |= ((1ull << mbits) - 1) & ~((1ull << ((r >> 16) % mbits)) - 1);
        }
        return sign | ((u64)e << mbits) | man;
    case 5:                                 /* huge */
        e = (1 << ebits) - 2 - (long)((r >> 8) % 3);
        return sign | ((u64)e << mbits) | man;
    case 6:                                 /* integer or half-integer, small */
        e = bias + (long)((r >> 8) % (esz == 1 ? 12 : 26));
        man &= ~((1ull << (mbits > (e - bias) ? mbits - (e - bias) - ((r >> 20) & 1) : 0)) - 1);
        if (mbits <= e - bias) {
            man &= (1ull << mbits) - 1;
        }
        return sign | ((u64)e << mbits) | (man & ((1ull << mbits) - 1));
    case 7:                                 /* about the integer range limits */
        e = bias + (esz == 1 ? 15 : (r >> 8) & 1 ? 31 : 63) - (long)((r >> 9) % 2);
        if (e >= (1 << ebits) - 1) {
            e = (1 << ebits) - 2;
        }
        man = (r >> 10) & 1 ? ((1ull << mbits) - 1) ^ (rnd() & 7) : rnd() & 7;
        return sign | ((u64)e << mbits) | man;
    default:                                /* ordinary */
        e = bias - 20 + (long)((r >> 8) % 41);
        return sign | ((u64)e << mbits) | man;
    }
}

static u64 int_lane(int esz)
{
    static const u64 edge[] = {
        0, 1, (u64)-1, 2, 0x7f, 0x80, 0x7fff, 0x8000, 0xffff, 0x7fffffff,
        0x80000000, 0xffffffff, 0x1000001, 0x7fffffffffffffffull,
        0x8000000000000000ull, 0x20000000000001ull, 0xffffffff00000001ull,
    };
    u64 r = rnd();

    switch (r % 4) {
    case 0:
        return edge[(r >> 8) % ELEMS(edge)];
    case 1:
        return (u64)((long)(rnd() % 2001) - 1000);
    case 2:
        return rnd() >> ((r >> 8) % 64);
    default:
        return rnd();
    }
}

static void put_lane(v128 *v, int esz, int i, u64 x)
{
    int bits = 8 << esz;
    u64 mask = bits == 64 ? ~0ull : (1ull << bits) - 1;
    int per = 64 / bits;
    u64 *w = i < per ? &v->lo : &v->hi;
    int sh = (i % per) * bits;

    *w = (*w & ~(mask << sh)) | ((x & mask) << sh);
}

static u64 get_lane(const v128 *v, int esz, int i)
{
    int bits = 8 << esz;
    u64 mask = bits == 64 ? ~0ull : (1ull << bits) - 1;
    int per = 64 / bits;

    return ((i < per ? v->lo : v->hi) >> ((i % per) * bits)) & mask;
}

static void fill(const struct test *t)
{
    int lanes = 16 >> t->esz;

    D.lo = rnd();
    D.hi = rnd();
    for (int i = 0; i < lanes; i++) {
        u64 n, m, a;
        u64 r = rnd();

        if (t->intin) {
            n = int_lane(t->esz);
            m = int_lane(t->esz);
            a = int_lane(t->esz);
        } else {
            n = fp_lane(t->esz);
            m = fp_lane(t->esz);
            a = fp_lane(t->esz);
            switch (r % 16) {
            case 0:                         /* equal, for compares and min/max */
                m = n;
                break;
            case 1:                         /* negated: exact cancellation */
                m = n ^ (1ull << ((8 << t->esz) - 1));
                break;
            case 2:                         /* fused: a = -(n * m) roughly */
                a = n ^ (1ull << ((8 << t->esz) - 1));
                m = t->esz == 1 ? 0x3c00 : t->esz == 2 ? 0x3f800000 : 0x3ff0000000000000ull;
                break;
            case 3:                         /* (max denormal) * (1 + ulp): rounds to min normal */
                n = (t->esz == 1 ? 0x03ffull : t->esz == 2 ? 0x007fffffull : 0x000fffffffffffffull)
                    - (rnd() & 3);
                m = (t->esz == 1 ? 0x3c00ull : t->esz == 2 ? 0x3f800000ull : 0x3ff0000000000000ull)
                    + 1 + (rnd() & 7);
                if (r & 0x100) {
                    n |= 1ull << ((8 << t->esz) - 1);
                }
                break;
            case 4:                         /* sums about the min normal */
                n = t->esz == 1 ? 0x0400 : t->esz == 2 ? 0x00800000 : 0x0010000000000000ull;
                n += rnd() & 15;
                m = (rnd() & 15) | (1ull << ((8 << t->esz) - 1));
                break;
            }
        }
        put_lane(&N, t->esz, i, n);
        put_lane(&M, t->esz, i, m);
        put_lane(&A, t->esz, i, a);
    }
}

#define SYSREG_R(name) ({ u64 _v; __asm__ volatile("mrs %0, " #name : "=r"(_v)); _v; })
#define SYSREG_W(name, v) __asm__ volatile("msr " #name ", %0" :: "r"((u64)(v)))

static u64 mix(u64 h, u64 v)
{
    h ^= v + 0x9e3779b97f4a7c15ull + (h << 6) + (h >> 2);
    h *= 0xff51afd7ed558ccdull;
    return h ^ (h >> 29);
}

#define FPCR_FIZ  (1u << 0)
#define FPCR_AH   (1u << 1)
#define FPCR_NEP  (1u << 2)
#define FPCR_FZ16 (1u << 19)
#define FPCR_FZ   (1u << 24)
#define FPCR_DN   (1u << 25)
#define FPCR_AHP  (1u << 26)

static u32 configs[32];
static int nconfigs;

#ifdef DUMP
#ifndef DUMP_TEST
#define DUMP_TEST -1
#endif
static int dump_test = DUMP_TEST;
#endif

int main(void)
{
    u64 total = 0;
    int ntests = ELEMS(tests);

    for (u32 rm = 0; rm < 4; rm++) {
        for (u32 fz = 0; fz < 2; fz++) {
            for (u32 dn = 0; dn < 2; dn++) {
                configs[nconfigs++] = rm << 22 | fz * FPCR_FZ | dn * FPCR_DN;
            }
        }
    }
    configs[nconfigs++] = FPCR_AH;
    configs[nconfigs++] = FPCR_AH | FPCR_FZ | (1u << 22);
    configs[nconfigs++] = FPCR_FIZ;
    configs[nconfigs++] = FPCR_NEP | (2u << 22);
    configs[nconfigs++] = FPCR_FZ16;
    configs[nconfigs++] = FPCR_AHP | FPCR_DN;

    puts_("vphone-native-fp: ");
    putx(ntests);
    puts_(" forms, ");
    putx(nconfigs);
    puts_(" FPCR settings\n");

    for (int ti = 0; ti < ntests; ti++) {
        const struct test *t = &tests[ti];
        u64 h = 0;

        for (int c = 0; c < nconfigs; c++) {
            /* The same operands for each test whatever ran before it. */
            rng = SEED ^ ((u64)ti << 32) ^ ((u64)c << 16);
            SYSREG_W(fpcr, configs[c]);
            SYSREG_W(fpsr, 0);
            for (int i = 0; i < ITERS; i++) {
                u64 fpsr;

                fill(t);
                SYSREG_W(fpsr, 0);
                t->fn();
                fpsr = SYSREG_R(fpsr);
                h = mix(mix(mix(h, D.lo), D.hi), fpsr);
#ifdef DUMP
                if (dump_test < 0 || dump_test == ti) {
                    puts_(t->name);
                    puts_(" c");
                    putx(c);
                    puts_(" i");
                    putx(i);
                    puts_(" n=");
                    putx(N.hi); putx(N.lo);
                    puts_(" m=");
                    putx(M.hi); putx(M.lo);
                    puts_(" a=");
                    putx(A.hi); putx(A.lo);
                    puts_(" d=");
                    putx(D.hi); putx(D.lo);
                    puts_(" fpsr=");
                    putx(fpsr);
                    puts_("\n");
                }
#endif
            }
            /* Flags accumulated over a batch, an exception in the middle. */
            SYSREG_W(fpsr, 0);
            for (int i = 0; i < BATCH; i++) {
                fill(t);
                t->fn();
                h = mix(mix(h, D.lo), D.hi);
                if (i == BATCH / 2) {
                    __asm__ volatile("svc #0" ::: "memory");
                }
            }
            {
                u64 fpsr = SYSREG_R(fpsr);

                h = mix(h, fpsr);
#ifdef DUMP
                if (dump_test < 0 || dump_test == ti) {
                    puts_(t->name);
                    puts_(" c");
                    putx(c);
                    puts_(" batch fpsr=");
                    putx(fpsr);
                    puts_("\n");
                }
#endif
            }
            h = mix(h, SYSREG_R(fpcr));
        }
        puts_(t->name);
        puts_(" ");
        putx(h);
        puts_("\n");
        total = mix(total, h);
    }
    SYSREG_W(fpcr, 0);
    puts_("TOTAL ");
    putx(total);
    puts_("\n");
    (void)get_lane;
    return 0;
}
